      - reopened
      - unlocked
  merge_group:
    types: [checks_requested]

jobs:
  merge-queue:
    runs-on: ubuntu-latest
    steps:
      - name: Merge Queue Status
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo } = context.repo;
            const prNumber = context.payload.pull_request.number;

            // Check if PR has merge queue label
            const labels = context.payload.pull_request.labels.map(label => label.name);
            const isMergeQueue = labels.includes('merge-queue');

            if (!isMergeQueue) {
              console.log('PR does not have merge-queue label, skipping merge queue processing');
              return;
            }

            // Get current status checks
            const { data: statusChecks } = await github.rest.checks.listForRef({
              owner,
              repo,
              ref: context.payload.pull_request.head.sha
            });

            // Check if all required checks pass
            const requiredChecks = ['Build', 'Test', 'Lint'];
            const passingChecks = statusChecks.check_runs.filter(check => 
              requiredChecks.includes(check.name) && check.conclusion === 'success'
            );

